pub const Category = enum(u8) {
    uppercase_letter,
    lowercase_letter,
    titlecase_letter,
    modifier_letter,
    other_letter,
    nonspacing_mark,
    spacing_combining_mark,
    enclosing_mark,
    decimal_digit_number,
    letter_number,
    other_number,
    space_separator,
    line_separator,
    paragraph_separator,
    control,
    format,
    surrogate,
    private_use,
    connector_punctuation,
    dash_punctuation,
    open_punctuation,
    close_punctuation,
    initial_quote_punctuation,
    final_quote_punctuation,
    other_punctuation,
    math_symbol,
    currency_symbol,
    modifier_symbol,
    other_symbol,
    other_not_assigned,
};

/// `Char.GetUnicodeCategory c`
pub fn category(c: u16) Category {
    var lo: usize = 0;
    var hi: usize = category_starts.len;
    while (hi - lo > 1) {
        const mid = (lo + hi) / 2;
        if (category_starts[mid] <= c) lo = mid else hi = mid;
    }
    return @fromBackingInt(@intCast(category_values[lo]));
}

pub fn isDigit(c: u16) bool {
    return category(c) == .decimal_digit_number;
}

pub fn isLetter(c: u16) bool {
    return @backingInt(category(c)) <= @backingInt(Category.other_letter);
}

pub fn isLetterOrDigit(c: u16) bool {
    return isLetter(c) or isDigit(c);
}

pub fn isUpper(c: u16) bool {
    return category(c) == .uppercase_letter;
}

pub fn isLower(c: u16) bool {
    return category(c) == .lowercase_letter;
}

pub fn isNumber(c: u16) bool {
    const k = category(c);
    return k == .decimal_digit_number or k == .letter_number or k == .other_number;
}

pub fn isPunctuation(c: u16) bool {
    const k = @backingInt(category(c));
    return k >= @backingInt(Category.connector_punctuation) and k <= @backingInt(Category.other_punctuation);
}

pub fn isSymbol(c: u16) bool {
    const k = @backingInt(category(c));
    return k >= @backingInt(Category.math_symbol) and k <= @backingInt(Category.other_symbol);
}

pub fn isSeparator(c: u16) bool {
    const k = category(c);
    return k == .space_separator or k == .line_separator or k == .paragraph_separator;
}

pub fn isControl(c: u16) bool {
    return category(c) == .control;
}

pub fn isSurrogate(c: u16) bool {
    return c >= 0xD800 and c <= 0xDFFF;
}

pub const CaseRun = struct { lo: u16, hi: u16, stride: u8, delta: i32 };

fn map(table: []const CaseRun, c: u16) u16 {
    var lo: usize = 0;
    var hi: usize = table.len;
    while (lo < hi) {
        const mid = (lo + hi) / 2;
        if (table[mid].hi < c) lo = mid + 1 else hi = mid;
    }
    if (lo == table.len) return c;
    const run = table[lo];
    if (c < run.lo or (c - run.lo) % run.stride != 0) return c;
    return @intCast(@as(i32, c) + run.delta);
}

pub fn toUpper(c: u16) u16 {
    if (c < 0x80) return if (c >= 'a' and c <= 'z') c - 32 else c;
    return map(&to_upper, c);
}

pub fn toLower(c: u16) u16 {
    if (c < 0x80) return if (c >= 'A' and c <= 'Z') c + 32 else c;
    return map(&to_lower, c);
}

/// `Char.IsWhiteSpace`
pub fn isWhiteSpace(c: u16) bool {
    return switch (c) {
        0x09...0x0D, 0x20, 0x85, 0xA0, 0x1680, 0x2000...0x200A, 0x2028, 0x2029, 0x202F, 0x205F, 0x3000 => true,
        else => false,
    };
}

